import requests
from requests.utils import _parse_content_type_header

def test_malformed_content_type():
    # Valid case
    ct, params = _parse_content_type_header("text/html; charset=utf-8")
    assert ct == "text/html"
    assert params == {"charset": "utf-8"}

    # Malformed case: parameter without '='
    ct, params = _parse_content_type_header("text/html; malformed")
    assert ct == "text/html"
    assert params == {}

    # Mixed case
    ct, params = _parse_content_type_header("text/html; charset=utf-8; malformed")
    assert ct == "text/html"
    assert params == {"charset": "utf-8"}

if __name__ == "__main__":
    try:
        test_malformed_content_type()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)

